<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref,watch } from 'vue'
import ShotDetails, { type Shot } from './ShotDetails.vue'
type Kind='novel'|'script'|'character'|'scene'|'relationship'|'episode'|'storyboard'|'generation_plan'
interface Entry {id:string;project_id:string;kind:Kind;current_version:number;version:number;version_id:string;title:string;content:Record<string,any>;content_hash:string;note:string;provenance:Record<string,unknown>}
interface Relation {from_character_version_id:string;to_character_version_id:string;description:string}
const props=defineProps<{projectId:string;assets:{id:string;name:string}[]}>()
const emit=defineEmits<{assetsChanged:[];production:[version:Entry];adaptation:[version:Entry]}>()
const kinds:Record<Kind,string>={novel:'小说',script:'剧本',character:'角色',scene:'场景',relationship:'人物关系',episode:'分集',storyboard:'分镜',generation_plan:'模型输入计划'}
function defaults(kind:Kind='novel'){return {kind,title:'',text:'',authorization:'',source_asset_id:null as string|null,description:'',appearance:'',personality:'',voice_description:'',voice_id:'',reference_audio_asset_id:null as string|null,reference_asset_ids:[] as string[],location:'',time_of_day:'',body:'',summary:'',source_version_id:null as string|null,character_version_ids:[] as string[],scene_version_ids:[] as string[],number:1,shots:[] as Shot[],relationships:[] as Relation[],capability:'text',prompt:'',input_version_ids:[] as string[],note:''}}
const form=reactive(defaults()),items=ref<Entry[]>([]),history=ref<Entry[]>([]),selected=ref<Entry|null>(null),pinned=ref<Record<string,Entry>>({})
const filter=ref<Kind>('novel'),busy=ref(false),error=ref(''),message=ref(''),cache=ref(''),estimate=ref(''),unitChars=ref(800),total=ref(0),offset=ref(0)
const diffLeft=ref(1),diffText=ref('')
const requestKey=ref(crypto.randomUUID()),currentProject=ref(props.projectId),deriveKeys=new Map<string,string>()
let restoring=false,initialized=false,cacheTimer:ReturnType<typeof setTimeout>|undefined
const historical=computed(()=>!!selected.value&&selected.value.version<selected.value.current_version)
const choices=computed(()=>Array.from(new Map([...items.value,...Object.values(pinned.value)].map(i=>[i.version_id,i])).values()))
const ofKind=(...types:Kind[])=>choices.value.filter(i=>types.includes(i.kind))
const imageAssets=computed(()=>props.assets.filter(a=>/\.(png|jpe?g|webp)$/i.test(a.name)))
const audioAssets=computed(()=>props.assets.filter(a=>/\.(wav|mp3)$/i.test(a.name)))
const label=(i:Entry)=>`${i.title} · v${i.version}${i.version<i.current_version?'（历史）':''}`
async function api<T=any>(path:string,options:RequestInit={}):Promise<T>{const response=await fetch('/api'+path,options);const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data}
function post(path:string,body:unknown){return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}
function persist(){if(restoring||!currentProject.value)return;try{sessionStorage.setItem(`ai-story:creative-draft:${currentProject.value}`,JSON.stringify({form:{...form},selected:selected.value,requestKey:requestKey.value}));cache.value='当前浏览器草稿已缓存；保存后才写入数据库'}catch{cache.value='浏览器草稿缓存不可用，请及时保存到数据库'}}
watch(form,()=>{if(restoring)return;clearTimeout(cacheTimer);cacheTimer=setTimeout(persist,300)},{deep:true})
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function refresh(){if(!props.projectId){items.value=[];return}const data=await api<{items:Entry[];total:number}>(`/projects/${props.projectId}/story/entities?offset=${offset.value}&limit=200`);for(const entry of items.value)pinned.value[entry.version_id]=entry;items.value=data.items;total.value=data.total}
function fresh(kind:Kind=filter.value){restoring=true;Object.assign(form,defaults(kind));selected.value=null;history.value=[];estimate.value='';requestKey.value=crypto.randomUUID();message.value='';restoring=false;persist()}
function collectRefs(content:unknown):string[]{if(!content||typeof content!=='object')return [];const refs:string[]=[];for(const [key,value] of Object.entries(content)){if(key.endsWith('_version_id')&&typeof value==='string')refs.push(value);else if(key.endsWith('_version_ids')&&Array.isArray(value))refs.push(...value.filter(v=>typeof v==='string'));else if(typeof value==='object')refs.push(...collectRefs(value))}return refs}
async function loadPins(item:Entry){const ids=[...new Set(collectRefs(item.content))].filter(id=>!choices.value.some(i=>i.version_id===id));const results=await Promise.all(ids.map(id=>api<Entry>(`/story/versions/${id}`)));for(const entry of results)pinned.value[entry.version_id]=entry}
async function load(item:Entry){message.value='';if(!item.content)item=await api<Entry>(`/story/versions/${item.version_id}`);restoring=true;selected.value=item;filter.value=item.kind;Object.assign(form,defaults(item.kind),{title:item.title,note:''});const c=item.content
 for(const key of ['text','authorization','source_asset_id','description','appearance','personality','reference_asset_ids','location','time_of_day','body','summary','source_version_id','character_version_ids','scene_version_ids','number','shots','relationships','capability','prompt','input_version_ids'])if(c[key]!==undefined)(form as any)[key]=structuredClone(c[key])
 if(item.kind==='storyboard') form.shots=form.shots.map(shot=>({framing:null,speaker_version_id:null,strategy:'manual',...shot,shot_id:shot.shot_id || item.id+'-'+shot.number}))
 if(c.voice){form.voice_description=c.voice.description;form.voice_id=c.voice.voice_id;form.reference_audio_asset_id=c.voice.reference_audio_asset_id}
 requestKey.value=crypto.randomUUID();estimate.value='';diffText.value='';restoring=false;persist()
 await loadPins(item);history.value=await api<Entry[]>(`/story/entities/${item.id}/versions`)
}
function content(){switch(form.kind){case 'novel':return {text:form.text,authorization:form.authorization,source_asset_id:form.source_asset_id};case 'character':return {description:form.description,appearance:form.appearance,personality:form.personality,reference_asset_ids:form.reference_asset_ids,voice:{description:form.voice_description,voice_id:form.voice_id,reference_audio_asset_id:form.reference_audio_asset_id,provider:'disabled'}};case 'scene':return {description:form.description,location:form.location,time_of_day:form.time_of_day,reference_asset_ids:form.reference_asset_ids};case 'script':case 'episode':return {body:form.body,summary:form.summary,source_version_id:form.source_version_id,character_version_ids:form.character_version_ids,scene_version_ids:form.scene_version_ids,...(form.kind==='episode'?{number:form.number}:{})};case 'relationship':return {relationships:form.relationships};case 'storyboard':return {source_version_id:form.source_version_id,shots:form.shots};case 'generation_plan':return {capability:form.capability,prompt:form.prompt,input_version_ids:form.input_version_ids}}}
async function save(){await run(async()=>{const result=await post(selected.value?`/story/entities/${selected.value.id}/versions`:`/projects/${props.projectId}/story/entities`,{title:form.title,content:content(),idempotency_key:requestKey.value,note:form.note,...(selected.value?{expected_version:selected.value.current_version}:{kind:form.kind})});await refresh();await load(result);message.value=`已保存数据库版本 v${result.version}；历史内容保留`})}
async function restore(){if(!selected.value)return;await run(async()=>{const result=await post(`/story/entities/${selected.value!.id}/restore`,{expected_version:selected.value!.current_version,version:selected.value!.version,idempotency_key:requestKey.value});await refresh();await load(result);message.value='已追加恢复版本，原有历史未覆盖'})}
async function derive(operation:string){if(!selected.value)return;await run(async()=>{const signature=JSON.stringify({id:selected.value!.version_id,operation,unit_chars:unitChars.value});if(!deriveKeys.has(signature))deriveKeys.set(signature,crypto.randomUUID());const result=await post(`/projects/${props.projectId}/story/derive`,{source_version_id:selected.value!.version_id,operation,unit_chars:unitChars.value,idempotency_key:deriveKeys.get(signature)});await refresh();await load(result.items[0]);message.value=`已保存 ${result.items.length} 项规则草稿；非 AI 生成，须人工审核`})}
async function importText(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;await run(async()=>{if(file.size>2*1024*1024)throw new Error('文本文件超过2 MiB');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()).replace(/^\uFEFF/,'');const body=new FormData();body.append('file',file);body.append('authorization',form.authorization);const result=await api(`/projects/${props.projectId}/assets`,{method:'POST',body});form.text=text;form.source_asset_id=result.id;if(!form.title)form.title=file.name.replace(/\.txt$/i,'');emit('assetsChanged');message.value='原始 TXT 已保存为素材；请保存小说版本以建立引用'});input.value=''}
function addShot(){form.shots.push({shot_id:crypto.randomUUID(),framing:null,speaker_version_id:null,strategy:'manual',number:Math.max(0,...form.shots.map(s=>s.number))+1,description:'',dialogue:'',planned_duration:3,scene_version_id:null,character_version_ids:[]})}
function addRelation(){form.relationships.push({from_character_version_id:'',to_character_version_id:'',description:''})}
async function compare(){if(!selected.value)return;await run(async()=>{const result=await api(`/story/entities/${selected.value!.id}/compare?left=${diffLeft.value}&right=${selected.value!.version}`);diffText.value=(result.truncated?'仅显示前262144字符\n':'')+(result.diff||'两个版本的标题与内容相同')})}
async function moreHistory(){if(!selected.value)return;await run(async()=>{const result=await api<Entry[]>(`/story/entities/${selected.value!.id}/versions?offset=${history.value.length}&limit=100`);history.value=[...new Map([...history.value,...result].map(v=>[v.version_id,v])).values()]})}
async function readEstimate(){if(!selected.value)return;await run(async()=>{const result=await api(`/story/entities/${selected.value!.id}/model-estimate?version=${selected.value!.version}`);estimate.value=`未执行模型调用；费用未知：${result.reason}`})}
async function enterProject(project:string){clearTimeout(cacheTimer);if(initialized)persist();restoring=true;currentProject.value=project;items.value=[];history.value=[];pinned.value={};selected.value=null;offset.value=0;Object.assign(form,defaults());requestKey.value=crypto.randomUUID();try{const saved=JSON.parse(sessionStorage.getItem(`ai-story:creative-draft:${project}`)||'null');if(saved){Object.assign(form,saved.form);selected.value=saved.selected;requestKey.value=saved.requestKey;filter.value=form.kind;cache.value='已恢复浏览器草稿；数据库可能已有新版本，保存时会检查冲突'}}catch{cache.value='草稿恢复失败，可从数据库历史重新打开'}restoring=false;initialized=true;await refresh();if(selected.value){await loadPins(selected.value);history.value=await api(`/story/entities/${selected.value.id}/versions`)}}
watch(()=>props.projectId,project=>{void run(()=>enterProject(project))})
onMounted(()=>{void run(()=>enterProject(props.projectId))})
onUnmounted(()=>{clearTimeout(cacheTimer);persist()})
</script>

<template>
 <p v-if="!projectId" class="empty">先选择或创建项目，再建立创作资产。</p>
 <div v-else class="story-studio">
  <div class="actions"><h2>创作资产与版本</h2><button :disabled="busy" @click="run(refresh)">刷新资产库</button><a :href="`/api/projects/${projectId}/story/export`">导出创作包 JSON</a></div>
  <p class="hint">小说、剧本、角色、场景和分镜均保存独立版本。规则整理保留或拆分原文；AI 改写、图像视频生成和配音尚未启用。</p>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
  <div class="story-layout">
   <section class="story-library"><label>资产类型<select v-model="filter"><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select></label><button :disabled="busy" @click="fresh(filter)">新建{{kinds[filter]}}</button><p v-if="!items.some(i=>i.kind===filter)" class="hint">此页暂无{{kinds[filter]}}。</p><button v-for="item in items.filter(i=>i.kind===filter)" :key="item.id" :class="['story-item',{active:selected?.id===item.id}]" :disabled="busy" @click="run(()=>load(item))"><strong>{{item.title}}</strong><span>v{{item.version}} · {{kinds[item.kind]}}</span></button><p class="hint">共 {{total}} 项，当前第 {{Math.floor(offset/200)+1}} 页</p><div class="actions"><button :disabled="busy||offset===0" @click="offset-=200;run(refresh)">上一页</button><button :disabled="busy||offset+200>=total" @click="offset+=200;run(refresh)">下一页</button></div></section>
   <section class="story-editor">
    <h2>{{selected?'编辑':'新建'}}{{kinds[form.kind]}} <span v-if="selected">查看 v{{selected.version}} / 当前 v{{selected.current_version}}</span></h2><p class="hint">{{cache}}</p><p v-if="historical" class="hint">当前为历史版本。可查看或追加恢复版本，不会覆盖旧记录。</p>
    <form @submit.prevent="save"><fieldset :disabled="busy||historical"><label>标题<input v-model="form.title" required maxlength="200"></label>
     <template v-if="form.kind==='novel'"><label>素材授权来源<textarea v-model="form.authorization" required maxlength="10000" placeholder="自有原创声明或授权协议来源"></textarea></label><label>导入 UTF-8 TXT<input type="file" accept=".txt" :disabled="!form.authorization.trim()" @change="importText"></label><label>小说原文<textarea v-model="form.text" class="long-text" required maxlength="1000000"></textarea></label></template>
     <template v-if="form.kind==='character'"><label>角色说明<textarea v-model="form.description" maxlength="20000"></textarea></label><label>外貌与固定特征<textarea v-model="form.appearance" maxlength="20000"></textarea></label><label>性格与行为约束<textarea v-model="form.personality" maxlength="20000"></textarea></label><label>声音说明（仅配置，未生成）<textarea v-model="form.voice_description" maxlength="10000"></textarea></label><label>声音标识<input v-model="form.voice_id" maxlength="200" placeholder="后续适配器使用；当前不调用模型"></label><label>已授权声音参考<select v-model="form.reference_audio_asset_id"><option :value="null">不关联</option><option v-for="a in audioAssets" :key="a.id" :value="a.id">{{a.name}}</option></select></label></template>
     <template v-if="form.kind==='scene'"><label>场景描述<textarea v-model="form.description" maxlength="20000"></textarea></label><label>地点<input v-model="form.location" maxlength="1000"></label><label>时间与光线<input v-model="form.time_of_day" maxlength="200"></label></template>
     <label v-if="['character','scene'].includes(form.kind)">参考图片（先在素材中心导入并记录授权）<select v-model="form.reference_asset_ids" multiple><option v-for="a in imageAssets" :key="a.id" :value="a.id">{{a.name}}</option></select></label>
     <template v-if="['script','episode'].includes(form.kind)"><label v-if="form.kind==='episode'">集数<input v-model.number="form.number" type="number" min="1" max="1000" required></label><label>剧情摘要<textarea v-model="form.summary" maxlength="20000"></textarea></label><label>剧本正文<textarea v-model="form.body" class="long-text" required maxlength="1000000"></textarea></label><label>来源版本<select v-model="form.source_version_id"><option :value="null">自编，无来源引用</option><option v-for="e in ofKind('novel','script','episode')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label><div class="editor-grid"><label>角色版本<select v-model="form.character_version_ids" multiple><option v-for="e in ofKind('character')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label><label>场景版本<select v-model="form.scene_version_ids" multiple><option v-for="e in ofKind('scene')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label></div></template>
     <template v-if="form.kind==='relationship'"><button type="button" @click="addRelation">添加人物关系</button><div v-for="(r,index) in form.relationships" :key="index" class="story-row"><label>人物一<select v-model="r.from_character_version_id" required><option value="">选择角色版本</option><option v-for="e in ofKind('character')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label><label>人物二<select v-model="r.to_character_version_id" required><option value="">选择角色版本</option><option v-for="e in ofKind('character')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label><label>关系说明<textarea v-model="r.description" required maxlength="2000"></textarea></label><button type="button" @click="form.relationships.splice(index,1)">移除此草稿关系</button></div></template>
     <template v-if="form.kind==='storyboard'"><label>来源剧本或分集版本<select v-model="form.source_version_id" required><option :value="null">选择来源版本</option><option v-for="e in ofKind('script','episode')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label><button type="button" :disabled="form.shots.length>=200" @click="addShot">添加镜头</button><div v-for="(shot,index) in form.shots" :key="index" class="story-row"><div class="editor-grid"><label>镜头编号<input v-model.number="shot.number" type="number" min="1" max="1000" required></label><label>计划时长（秒，非实际输出）<input v-model.number="shot.planned_duration" type="number" min="0.2" max="120" step="0.1" required></label></div><label>画面说明<textarea v-model="shot.description" required maxlength="10000"></textarea></label><label>对白<textarea v-model="shot.dialogue" maxlength="10000"></textarea></label><div class="editor-grid"><label>场景版本<select v-model="shot.scene_version_id"><option :value="null">待人工设定</option><option v-for="e in ofKind('scene')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label><label>角色版本<select v-model="shot.character_version_ids" multiple><option v-for="e in ofKind('character')" :key="e.version_id" :value="e.version_id">{{label(e)}}</option></select></label></div><ShotDetails :shot="shot" :characters="ofKind('character')" /><button type="button" @click="form.shots.splice(index,1)">移除此草稿镜头</button></div></template>
     <template v-if="form.kind==='generation_plan'"><p class="hint">保存输入计划仅用于准备与导出，不会生成内容或扣费。</p><label>后续模型能力<select v-model="form.capability"><option value="text">文本</option><option value="speech">语音</option><option value="image">图像</option><option value="video">视频</option></select></label><label>提示词<textarea v-model="form.prompt" class="long-text" required maxlength="100000"></textarea></label><label>固定输入版本<select v-model="form.input_version_ids" multiple><option v-for="e in choices" :key="e.version_id" :value="e.version_id">{{kinds[e.kind]}} · {{label(e)}}</option></select></label></template>
     <label>本次版本说明<textarea v-model="form.note" maxlength="10000"></textarea></label><button class="primary" :disabled="!form.title.trim()">{{selected?'保存新版本':'创建资产 v1'}}</button>
    </fieldset></form>
    <div v-if="historical" class="actions"><button :disabled="busy" @click="restore">从此历史追加恢复版本</button></div>
    <div v-if="selected" class="story-tools"><h2>基于已保存版本的操作</h2><p class="hint">规则工具只保留/拆分原文。3秒默认镜头时长仅是可编辑计划，所有草稿须人工审核。</p><label v-if="['novel','script','episode'].includes(selected.kind)">拆分目标字数<input v-model.number="unitChars" type="number" min="100" max="10000"></label><div class="actions"><button v-if="['novel','script','episode'].includes(selected.kind)" :disabled="busy" @click="derive('structure_script')">整理为剧本草稿</button><button v-if="selected.kind==='script'" :disabled="busy" @click="derive('split_episodes')">规则拆分分集</button><button v-if="['script','episode'].includes(selected.kind)" :disabled="busy" @click="derive('split_shots')">规则拆分分镜</button><button v-if="['script','episode','storyboard'].includes(selected.kind)" :disabled="busy" @click="emit('production',selected)">引用此版本创建剪辑批次</button><button v-if="['novel','script','episode'].includes(selected.kind)" :disabled="busy" @click="emit('adaptation',selected)">使用此版本改编剧情</button><button v-if="selected.kind==='generation_plan'" :disabled="busy" @click="readEstimate">查看模型接入状态</button></div><p v-if="estimate" class="hint">{{estimate}}</p><p v-if="['script','episode','storyboard'].includes(selected.kind)" class="hint">生产入口使用用户已有视频，仅记录本版本依据；不会自动生成镜头或执行分镜计划。</p><h2>版本历史</h2><div class="version-list"><button v-for="version in history" :key="version.version_id" :disabled="busy" @click="run(()=>load(version))">v{{version.version}} · {{version.note||'未填版本说明'}}</button></div><button v-if="history.length<selected.current_version" :disabled="busy" @click="moreHistory">加载更多历史</button><div class="actions"><label>比较来源版本<select v-model.number="diffLeft"><option v-for="version in history" :key="version.version_id" :value="version.version">v{{version.version}}</option></select></label><button :disabled="busy" @click="compare">与正在查看的版本比较</button></div><pre v-if="diffText" class="log-tail">{{diffText}}</pre><p class="mono">版本 {{selected.version_id}}<br>SHA-256 {{selected.content_hash}}</p></div>
   </section>
  </div>
 </div>
</template>
